 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    frames = []
    border_cells = set()

    # A frame is a monochrome rectangular outline with an empty interior.
    for color in range(1, 10):
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if not cells:
            continue
        r0 = min(r for r, c in cells); r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells); c1 = max(c for r, c in cells)
        if r1 - r0 < 2 or c1 - c0 < 2:
            continue
        perimeter = {(r, c) for r in range(r0, r1 + 1) for c in range(c0, c1 + 1)
                     if r in (r0, r1) or c in (c0, c1)}
        if not perimeter.issubset(set(cells)):
            continue
        if any(grid[r][c] != 0 for r in range(r0 + 1, r1) for c in range(c0 + 1, c1)):
            continue
        frames.append((r0, r1, c0, c1, color))
        border_cells.update(perimeter)

    # The scattered color tokens encode how many checkerboard cells to place.
    counts = Counter(grid[r][c] for r in range(h) for c in range(w)
                     if grid[r][c] != 0 and (r, c) not in border_cells)
    tokens = {color: n for color, n in counts.items() if n}

    for r0, r1, c0, c1, border in frames:
        inside = [(r, c) for r in range(r0 + 1, r1) for c in range(c0 + 1, c1)]
        target = sum((r - r0 - 1 + c - c0 - 1) % 2 == 0 for r, c in inside)
        color = min(tokens, key=lambda k: (abs(tokens[k] - target), k))
        for r, c in inside:
            out[r][c] = color if (r - r0 - 1 + c - c0 - 1) % 2 == 0 else 0
    # Remove the scattered tokens; retain only the frames and their patterned fills.
    for r in range(h):
        for c in range(w):
            if (r, c) not in border_cells and all(not (a < r < b and d < c < e) for a, b, d, e, _ in frames):
                out[r][c] = 0
    return out
